text = ("RAG systems split documents into chunks. Each chunk is embedded separately. "
        "Small chunks are precise but can lose context.\n\n"
        "Large chunks keep context but may mix several topics. "
        "Overlap between chunks helps keep sentences that sit on a boundary.")

def fixed_chunks(text, size=60, overlap=15):
    # Cut every `size` characters; each chunk repeats the last `overlap` chars
    step = size - overlap
    return [text[i:i + size] for i in range(0, len(text), step)]

def recursive_chunks(text, max_len=120):
    # Try big separators first (paragraphs), then sentences, keep pieces whole
    chunks = []
    for para in text.split("\n\n"):
        if len(para) <= max_len:
            chunks.append(para)
            continue
        current = ""
        for sentence in para.split(". "):
            piece = sentence if sentence.endswith(".") else sentence + "."
            if current and len(current) + len(piece) + 1 > max_len:
                chunks.append(current)
                current = piece
            else:
                current = (current + " " + piece).strip()
        if current:
            chunks.append(current)
    return chunks

print("FIXED (notice words cut in half):")
for c in fixed_chunks(text)[:4]:
    print("  |" + c.replace("\n", " ") + "|")
print("\nRECURSIVE (respects paragraphs and sentences):")
for c in recursive_chunks(text):
    print("  |" + c + "|")
